11	use Illuminate\Support\Facades\Storage;
12	use Spatie\MediaLibrary\MediaCollections\Models\Media;
13	use Tests\TestCase;
14	
15	/**
16	 * Link pubblico permanente al singolo asset (roadmap #33).
17	 *
18	 * L'asset non pubblicato non è raggiungibile senza sessione; quello pubblicato
19	 * sì, con un URL stabile che serve sempre il contenuto corrente e che la revoca
20	 * riporta a 404.
21	 */
22	class PublicAssetLinkTest extends TestCase
23	{
24	    use RefreshDatabase;
25	
26	    public function test_unpublished_asset_has_no_public_url(): void
27	    {
28	        $media = $this->makeMedia();
29	
30	        $this->assertFalse(AssetPublication::isPublished($media));
31	        $this->assertNull(AssetUrl::publicOriginal($media));
32	    }
33	
34	    public function test_published_asset_is_served_without_session(): void
35	    {
36	        $media = $this->makeMedia();
37	        AssetPublication::publish($media);
38	
39	        $url = AssetUrl::publicOriginal($media);
40	        $this->assertIsString($url);
41	
42	        $this->get($url)
43	            ->assertOk()
44	            ->assertHeader('content-type', 'image/jpeg');
45	    }
46	
47	    public function test_unknown_token_gets_404(): void
48	    {
49	        $this->makeMedia();
50	
51	        $this->get(route('digital-hub.assets.public', ['token' => 'non-esiste']))
52	            ->assertNotFound();
53	    }
54	
55	    /**
56	     * Il link è permanente: ripubblicare non deve rigenerare il token, altrimenti
57	     * il secondo consumatore che linka lo stesso documento (#34) romperebbe i
58	     * link del primo.
59	     */
60	    public function test_publishing_twice_keeps_the_same_token(): void
61	    {
62	        $media = $this->makeMedia();
63	
64	        $first = AssetPublication::publish($media);
65	        $second = AssetPublication::publish($media->fresh());
66	
67	        $this->assertSame($first, $second);
68	    }
69	
70	    /**
71	     * URL stabile che serve sempre il contenuto corrente: dopo una sostituzione
72	     * del file (22i) il link resta lo stesso e restituisce i byte nuovi.
73	     */
74	    public function test_public_url_serves_the_current_content_after_replace(): void
75	    {
76	        $media = $this->makeMedia();
77	        AssetPublication::publish($media);
78	        $url = (string) AssetUrl::publicOriginal($media);
79	
80	        Storage::disk($media->disk)->put($media->getPathRelativeToRoot(), 'contenuto-nuovo');
81	
82	        $this->assertSame($url, AssetUrl::publicOriginal($media->fresh()));
83	        $this->assertSame('contenuto-nuovo', $this->get($url)->streamedContent());
84	    }
85	
86	    public function test_revoking_breaks_the_link(): void
87	    {
88	        $media = $this->makeMedia();
89	        AssetPublication::publish($media);
90	        $url = (string) AssetUrl::publicOriginal($media);
91	
92	        AssetPublication::revoke($media);
93	
94	        $this->get($url)->assertNotFound();
95	        $this->assertNull(AssetUrl::publicOriginal($media));
96	    }
97	
98	    private function makeMedia(): Media
99	    {
100	        Storage::fake('assets');
101	
102	        $product = Product::create(['name' => ['it' => 'Tavolo']]);
103	
104	        return $product
105	            ->addMediaFromString($this->jpeg())
106	            ->usingFileName('photo.jpg')
107	            ->toMediaCollection('assets');
108	    }
109	
110	    private function jpeg(): string
111	    {
112	        $image = imagecreatetruecolor(20, 20);
113	        ob_start();
114	        imagejpeg($image);
115	        $data = (string) ob_get_clean();
116	        imagedestroy($image);
117	
118	        return $data;
119	    }
120	}
